class Circulo:
    def __init__(self, r):
        self.r = r
    def area(self):
        return round(3.1416 * self.r ** 2, 2)

class Cuadrado:
    def __init__(self, lado):
        self.lado = lado
    def area(self):
        return self.lado ** 2

formas = [Circulo(2), Cuadrado(3)]
for f in formas:
    print(type(f).__name__, f.area())
